package com.profa.review;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="reviews")public class Review{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID bookingId;UUID authorId;UUID teacherId;int rating;@Column(length=2000)String comment;Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getBookingId(){return bookingId;}public void setBookingId(UUID v){bookingId=v;}public UUID getAuthorId(){return authorId;}public void setAuthorId(UUID v){authorId=v;}public UUID getTeacherId(){return teacherId;}public void setTeacherId(UUID v){teacherId=v;}public int getRating(){return rating;}public void setRating(int v){rating=v;}public String getComment(){return comment;}public void setComment(String v){comment=v;}}